# bash completion for sl -- generated by tools/completions, do not edit
#
# Install: /usr/share/bash-completion/completions/sl (loaded automatically),
# or:      source completions/sl.bash

_sl() {
    local cur prev name
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"

    # --option=value: values attached with an equals sign
    if [[ $cur == --*=* ]]; then
        name="${cur%%=*}"
        name="${name#--}"
        case $name in
        color) COMPREPLY=( $(compgen -W "auto always never" -- "${cur#*=}") ); return ;;
        ignore) COMPREPLY=( $(compgen -W "0 1 2 3" -- "${cur#*=}") ); return ;;
        esac
        return
    fi

    # the value of the previous option
    case $prev in
        --age) return ;;   # a value: bash completes it
        --annotate) return ;;   # a value: bash completes it
        --annotate-batch) return ;;   # a value: bash completes it
        --annotate-match) return ;;   # a value: bash completes it
        --atime) return ;;   # a value: bash completes it
        --autosearch) return ;;   # a value: bash completes it
        --colsep) return ;;   # a value: bash completes it
        --config) return ;;   # a path: bash completes it
        --ellipsis) return ;;   # a value: bash completes it
        --expando) return ;;   # a value: bash completes it
        --ignore) COMPREPLY=( $(compgen -W "0 1 2 3" -- "$cur") ); return ;;
        --mounts) return ;;   # a path: bash completes it
        --namemin) return ;;   # a value: bash completes it
        --prefix) return ;;   # a value: bash completes it
        --relchange) return ;;   # a value: bash completes it
        --relread) return ;;   # a value: bash completes it
        --relsize) return ;;   # a value: bash completes it
        --series) return ;;   # a value: bash completes it
        --shorten) return ;;   # a value: bash completes it
        --startup) return ;;   # a path: bash completes it
        --summary) return ;;   # a value: bash completes it
        --width) return ;;   # a value: bash completes it
    esac

    # --rule takes "RE -> GROUP"; once a --rule is on the line, the words after
    # it belong to the rule, and after the arrow only a group name makes sense
    local i
    for (( i=1; i < COMP_CWORD; i++ )); do
        if [[ ${COMP_WORDS[i]} == --rule ]]; then
            # A rule is "RE -> GROUP" and may be typed as one word or as
            # several. Three cases, and the arrow decides which one:
            #   --rule RE -> |TAB        arrow is a word of its own: a bare group
            #   --rule RE -> im|TAB      same, with a prefix
            #   --rule 'RE -> im'|TAB    arrow inside the word: keep the prefix
            # Candidates contain a space, so they are filtered by hand:
            # compgen -W splits its word list on IFS.
            local head="" bare=0
            if [[ $prev == '->' ]]; then
                bare=1
            elif [[ $cur == *'->'* && $cur != '->'* ]]; then
                head="${cur%->*}"
            elif [[ $prev == *'->' ]]; then
                head="${prev%->*}"
            else
                return
            fi
            local g cand
            for g in special dir build app dev A2 WWW aux doc book document image vector audio video font data other archive dotfile Mac file ignore; do
                if (( bare )); then
                    [[ $g == "$cur"* ]] && COMPREPLY+=( "$g" )
                    continue
                fi
                cand="${head}-> ${g}"
                [[ $cand == "$cur"* ]] && COMPREPLY+=( "$cand" )
            done
            return
        fi
    done

    case $cur in
        --*)
            COMPREPLY=( $(compgen -W "--age --all --annotate --annotate-batch --annotate-match --atime --autosearch --color --colsep --config --ellipsis --expando --experimental --group --group-mix --help --ignore --inline-singleton --k1000 --k1024 --legacy-classify --legacy-series --log --mounts --namemin --no-color --no-config --no-notable --no-owner-notes --nogroup --nosfx --notable --one --only --owner-notes --prefix --relchange --relread --relsize --rule --series --shorten --startup --summary --title --version --width" -- "$cur") )
            return ;;
        -*)
            COMPREPLY=( $(compgen -W "-a -c -h -l -1 -o -t -V -w" -- "$cur") )
            return ;;
    esac
}

complete -o filenames -F _sl sl
